struct Node;

/// The store key under which the subscription list is kept. The value is
/// one feed URL per line.
const SUBSCRIPTIONS_KEY: &str = "subscriptions";

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        // Not added: `aap:caps/http-client@0.1.0`. The graph definition
        // declares only `StateHandle<'subscriptions', read>` for this node,
        // and the enrichment request would send data to
        // `metadata.internal.example`, a host outside that declared
        // capability set. `RunInfo` also has no text field to query with.
        // Add the import and the call once the graph definition grants it.
        //
        // `ensures present(urls)` is met by always returning the field:
        // a missing or empty store yields an empty list, since the return
        // type cannot carry an error.
        let urls = match crate::aap::caps::state_read::get(SUBSCRIPTIONS_KEY) {
            Some(raw) => raw
                .lines()
                .map(str::trim)
                .filter(|line| !line.is_empty())
                .map(String::from)
                .collect(),
            None => Vec::new(),
        };

        SubscriptionList { urls }
    }
}

export!(Node);
